import express from 'express';
import * as M from '../../models/index.js';
import { requirePerm } from '../../middleware/auth.js';
import { ah, badRequest, conflict, notFound } from '../../utils/errors.js';
import { runCommand } from '../../services/command.js';
import { emit } from '../../services/eventBus.js';
import { makeId, summarizeStock, itemAvailability, changeBalance, reserveLine, releaseReservation } from './logistics.service.js';

export const logisticsApi = express.Router();
const pageOf = (q) => ({ page: Math.max(1, Number.parseInt(q.page,10)||1), limit: Math.min(200, Math.max(1, Number.parseInt(q.limit,10)||50)) });
const meta = (total,page,limit) => ({ total,page,pageSize:limit,totalPages:Math.ceil(total/limit),hasNextPage:page<Math.ceil(total/limit),hasPreviousPage:page>1 });
const rx = (s) => new RegExp(String(s).replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'i');
const date = (v,k) => { const d=new Date(v);if(!v||Number.isNaN(d.getTime()))throw badRequest(`${k} must be a valid date`);return d; };
const actor = (req) => req.user?.email || 'system';
const execCommand = (req, action, entity, summary, fn, reason, event) => runCommand({user:req.user,action,entity,summary,reason,risk:'low',event},fn);
const paged = (rows,total,page,limit) => ({...meta(total,page,limit),rows});
const getItem = async (itemId) => {const item=await M.InventoryItem.findOne({itemId}).lean();if(!item)throw notFound('No such inventory item');return item;};
const makeMovement = async (req, fields, session) => M.StockMovement.create([{movementId:makeId('MOV'),by:actor(req),...fields}],session?{session}:{});
const pageRows = async (Model,q,req,res,sort={createdAt:-1}) => {const {page,limit}=pageOf(req.query);const [rows,total]=await Promise.all([Model.find(q).sort(sort).skip((page-1)*limit).limit(limit).lean(),Model.countDocuments(q)]);res.json(paged(rows,total,page,limit));};

// Categories
logisticsApi.get('/logistics/categories',requirePerm('inventory:read'),ah(async(req,res)=>{const q=req.query.active==='false'?{active:false}:{active:true};res.json({categories:await M.InventoryCategory.find(q).sort({name:1}).lean()});}));
logisticsApi.post('/logistics/categories',requirePerm('inventory:write'),ah(async(req,res)=>{const b=req.body||{};if(!b.categoryId||!b.name)throw badRequest('categoryId and name are required');const category=await M.InventoryCategory.create({...b});res.status(201).json({success:true,data:category});}));
logisticsApi.put('/logistics/categories/:id',requirePerm('inventory:write'),ah(async(req,res)=>{const data=Object.fromEntries(Object.entries(req.body||{}).filter(([k])=>['name','description','parentCategoryId','defaultUnit','trackingType','reorderThreshold','criticality','active'].includes(k)));const category=await M.InventoryCategory.findOneAndUpdate({categoryId:req.params.id},{$set:data},{new:true,runValidators:true});if(!category)throw notFound('No category');res.json({success:true,data:category});}));
logisticsApi.delete('/logistics/categories/:id',requirePerm('inventory:write'),ah(async(req,res)=>{const used=await M.InventoryItem.exists({categoryId:req.params.id});if(used)throw conflict('Category is in use; deactivate it instead');const c=await M.InventoryCategory.findOneAndUpdate({categoryId:req.params.id},{active:false},{new:true});if(!c)throw notFound('No category');res.json({success:true,data:c});}));

// Locations / warehouses
logisticsApi.get('/logistics/locations',requirePerm('inventory:read'),ah(async(req,res)=>pageRows(M.Location,req.query.status?{status:req.query.status}:{},req,res,{name:1})));
logisticsApi.get('/logistics/locations/:id/inventory',requirePerm('inventory:read'),ah(async(req,res)=>{const location=await M.Location.findOne({locationId:req.params.id}).lean();if(!location)throw notFound('No location');const [balances,assets]=await Promise.all([M.StockBalance.find({location:req.params.id}).lean(),M.Asset.find({locationId:req.params.id}).lean()]);const ids=[...new Set([...balances.map(b=>b.item),...assets.map(a=>a.itemId)])];const items=await M.InventoryItem.find({$or:[{itemId:{$in:ids}},{item:{$in:ids}},{itemName:{$in:ids}}]}).lean();res.json({locationId:req.params.id,items:items.map(i=>({item:i,...summarizeStock(balances.filter(b=>b.item===i.itemId||b.item===i.item||b.item===i.itemName)),assets:assets.filter(a=>a.itemId===i.itemId)}))});}));
logisticsApi.get('/logistics/locations/:id/capacity',requirePerm('inventory:read'),ah(async(req,res)=>{const location=await M.Location.findOne({locationId:req.params.id}).lean();if(!location)throw notFound('No location');const balances=await M.StockBalance.find({location:req.params.id}).lean();const used=balances.reduce((s,b)=>s+b.qty,0);res.json({locationId:location.locationId,capacity:location.capacity??null,used,availableCapacity:location.capacity==null?null:Math.max(0,location.capacity-used)});}));
logisticsApi.get('/logistics/locations/:id',requirePerm('inventory:read'),ah(async(req,res)=>{const location=await M.Location.findOne({locationId:req.params.id}).lean();if(!location)throw notFound('No location');res.json({location});}));
logisticsApi.post('/logistics/locations',requirePerm('inventory:write'),ah(async(req,res)=>{const b=req.body||{};if(!b.locationId||!b.name)throw badRequest('locationId and name are required');const location=await M.Location.create({...b});res.status(201).json({success:true,data:location});}));
logisticsApi.put('/logistics/locations/:id',requirePerm('inventory:write'),ah(async(req,res)=>{const fields=['name','locationType','parentLocationId','building','floor','room','address','coordinates','responsibleStaffId','capacity','status','notes'];const data=Object.fromEntries(Object.entries(req.body||{}).filter(([k])=>fields.includes(k)));const location=await M.Location.findOneAndUpdate({locationId:req.params.id},{$set:data},{new:true,runValidators:true});if(!location)throw notFound('No location');res.json({success:true,data:location});}));

// Inventory records and asset catalogue. Stock quantity is always read from stock balances.
for(const [path,state] of [['low-stock','available'],['damaged','damaged'],['missing','missing'],['maintenance-due','maintenance']]) logisticsApi.get(`/logistics/inventory/${path}`,requirePerm('inventory:read'),ah(async(req,res)=>{let items=await M.InventoryItem.find({}).lean();const balances=await M.StockBalance.find({state}).lean();const by=new Map();for(const b of balances)by.set(b.item,(by.get(b.item)||0)+b.qty);if(path==='low-stock')items=items.filter(i=>(by.get(i.itemId)||by.get(i.item)||by.get(i.itemName)||0)<=Number(i.reorderThreshold||0));else items=items.filter(i=>by.has(i.itemId)||by.has(i.item)||by.has(i.itemName)||((path==='maintenance-due')&&i.maintenanceDueAt&&i.maintenanceDueAt<=new Date()));res.json({rows:items.map(i=>({...i,quantity:by.get(i.itemId)||by.get(i.item)||by.get(i.itemName)||0}))});}));
logisticsApi.get('/logistics/inventory',requirePerm('inventory:read'),ah(async(req,res)=>{const q={};if(req.query.categoryId)q.categoryId=req.query.categoryId;if(req.query.ownership)q.ownership=req.query.ownership;if(req.query.criticality)q.criticality=req.query.criticality;if(req.query.q){const r=rx(req.query.q);q.$or=[{itemId:r},{item:r},{itemName:r},{sku:r},{categoryId:r}];}const {page,limit}=pageOf(req.query);const sortBy=req.query.sortBy==='cost'?'unitPurchaseCost':req.query.sortBy==='name'?'item':req.query.sortBy==='quantity'?'quantity':'itemId';const order=req.query.order==='desc'?-1:1;const [items,total,balances]=await Promise.all([M.InventoryItem.find(q).sort({[sortBy]:order}).skip((page-1)*limit).limit(limit).lean(),M.InventoryItem.countDocuments(q),M.StockBalance.find({}).lean()]);res.json(paged(items.map(i=>({...i,...summarizeStock(balances.filter(b=>b.item===i.itemId||b.item===i.item||b.item===i.itemName))})),total,page,limit));}));
logisticsApi.post('/logistics/inventory',requirePerm('inventory:write'),ah(async(req,res)=>{const b=req.body||{};if(!b.itemId||!(b.item||b.itemName)||!b.unit)throw badRequest('itemId, item name and unit are required');if(!['quantity','individual'].includes(b.trackingType||'quantity'))throw badRequest('trackingType must be quantity or individual');const opening=Number(b.openingQuantity||0);if(!Number.isInteger(opening)||opening<0)throw badRequest('openingQuantity must be a non-negative integer');if(opening&&(!b.location||!await M.Location.exists({locationId:b.location,status:'active'})))throw badRequest('Opening quantity requires an active location');const fields=['itemId','item','itemName','sku','description','categoryId','subcategory','brand','model','imageRef','itemType','ownership','trackingType','criticality','unit','reorderThreshold','minimumStock','maximumStock','unitPurchaseCost','replacementCost','currentBookValue','currentCustodian','operationalStatus','procurementDate','warrantyExpiry','maintenanceDueAt','notes'];const data=Object.fromEntries(Object.entries(b).filter(([k])=>fields.includes(k)));data.item=b.item||b.itemName;data.createdBy=actor(req);data.updatedBy=actor(req);const result=await execCommand(req,'INVENTORY_ITEM_CREATED',{type:'InventoryItem',id:b.itemId},{openingQuantity:opening,location:b.location},async(session)=>{const [item]=await M.InventoryItem.create([data],session?{session}:{});if(opening){await M.StockBalance.create([{item:item.item,location:b.location,state:'available',qty:opening}],session?{session}:{});await makeMovement(req,{item:item.item,itemId:item.itemId,qty:opening,to:{location:b.location,state:'available'},movementType:'adjustment',reason:'Opening stock',relatedRequestId:null},session);}return {summary:{itemId:item.itemId},result:{item}};});res.status(201).json({success:true,data:result});}));
logisticsApi.put('/logistics/inventory/:id',requirePerm('inventory:write'),ah(async(req,res)=>{const fields=['item','itemName','sku','description','categoryId','subcategory','brand','model','imageRef','itemType','ownership','trackingType','criticality','unit','reorderThreshold','minimumStock','maximumStock','unitPurchaseCost','replacementCost','currentBookValue','currentCustodian','operationalStatus','procurementDate','warrantyExpiry','maintenanceDueAt','notes'];const data=Object.fromEntries(Object.entries(req.body||{}).filter(([k])=>fields.includes(k)));data.updatedBy=actor(req);const item=await M.InventoryItem.findOneAndUpdate({itemId:req.params.id},{$set:data},{new:true,runValidators:true});if(!item)throw notFound('No item');res.json({success:true,data:item});}));
logisticsApi.patch('/logistics/inventory/:id/status',requirePerm('inventory:write'),ah(async(req,res)=>{const allowed=['available','partially_available','reserved','issued','maintenance','damaged','lost','retired','inactive'];if(!allowed.includes(req.body?.status))throw badRequest('Unsupported item status');const item=await M.InventoryItem.findOneAndUpdate({itemId:req.params.id},{$set:{operationalStatus:req.body.status,updatedBy:actor(req)}},{new:true});if(!item)throw notFound('No item');res.json({success:true,data:item});}));
logisticsApi.get('/logistics/inventory/:id/history',requirePerm('inventory:read'),ah(async(req,res)=>{const movements=await M.StockMovement.find({$or:[{itemId:req.params.id},{item:req.params.id}]}).sort({at:-1}).limit(500).lean();res.json({movements});}));
logisticsApi.get('/logistics/inventory/:id/availability',requirePerm('inventory:read'),ah(async(req,res)=>{const item=await getItem(req.params.id);const startAt=req.query.startAt?date(req.query.startAt,'startAt'):undefined;const endAt=req.query.endAt?date(req.query.endAt,'endAt'):undefined;if(startAt&&endAt&&endAt<=startAt)throw badRequest('endAt must be after startAt');res.json({itemId:item.itemId,...await itemAvailability(item.itemId,{locationId:req.query.locationId,startAt,endAt})});}));
logisticsApi.get('/logistics/inventory/:id',requirePerm('inventory:read'),ah(async(req,res)=>{const item=await getItem(req.params.id);const [balances,assets]=await Promise.all([M.StockBalance.find({item:{$in:[item.itemId,item.item,item.itemName].filter(Boolean)}}).lean(),M.Asset.find({itemId:item.itemId}).lean()]);res.json({item,...summarizeStock(balances),assets});}));

// Individual assets and scan lookup
logisticsApi.post('/logistics/assets',requirePerm('inventory:write'),ah(async(req,res)=>{const b=req.body||{};if(!b.assetId||!b.assetTag||!b.itemId)throw badRequest('assetId, assetTag and itemId are required');const item=await getItem(b.itemId);if(item.trackingType!=='individual')throw badRequest('Asset records require an individual-tracked item');const asset=await M.Asset.create({...b});res.status(201).json({success:true,data:asset});}));
logisticsApi.get('/logistics/assets/scan/:code',requirePerm('inventory:read'),ah(async(req,res)=>{const asset=await M.Asset.findOne({$or:[{assetTag:req.params.code},{serialNumber:req.params.code},{qrCode:req.params.code},{barcode:req.params.code},{assetId:req.params.code}]}).lean();if(!asset)throw notFound('No matching asset');res.json({asset});}));
logisticsApi.get('/logistics/assets/:id/qr-data',requirePerm('inventory:read'),ah(async(req,res)=>{const asset=await M.Asset.findOne({$or:[{assetId:req.params.id},{assetTag:req.params.id}]}).lean();if(!asset)throw notFound('No asset');res.json({assetId:asset.assetId,assetTag:asset.assetTag,scanCode:asset.qrCode||asset.barcode||asset.assetTag,lookupPath:`/api/logistics/assets/scan/${encodeURIComponent(asset.qrCode||asset.barcode||asset.assetTag)}`});}));

// Requests and reservation workflow
logisticsApi.get('/logistics/requests/pending',requirePerm('inventory:read'),ah(async(_req,res)=>res.json({rows:await M.ResourceRequest.find({status:{$in:['submitted','under_review']}}).sort({priority:-1,createdAt:1}).lean()})));
logisticsApi.get('/logistics/requests/by-event/:eventId',requirePerm('inventory:read'),ah(async(req,res)=>res.json({rows:await M.ResourceRequest.find({eventId:req.params.eventId}).sort({requiredAt:1}).lean()})));
logisticsApi.get('/logistics/requests/by-department/:departmentId',requirePerm('inventory:read'),ah(async(req,res)=>res.json({rows:await M.ResourceRequest.find({departmentId:req.params.departmentId}).sort({createdAt:-1}).lean()})));
logisticsApi.get('/logistics/requests',requirePerm('inventory:read'),ah(async(req,res)=>{const q={};for(const k of ['status','eventId','departmentId','priority'])if(req.query[k])q[k]=req.query[k];await pageRows(M.ResourceRequest,q,req,res,{createdAt:-1});}));
logisticsApi.post('/logistics/requests',requirePerm('inventory:request'),ah(async(req,res)=>{const b=req.body||{};if(!Array.isArray(b.lines)||!b.lines.length)throw badRequest('At least one item line is required');if(b.eventId&&!await M.Event.exists({eventId:b.eventId}))throw badRequest('Unknown eventId');if(b.venueId&&!await M.Venue.exists({venueId:b.venueId}))throw badRequest('Unknown venueId');for(const l of b.lines){if(!l.itemId||!Number.isInteger(Number(l.requestedQty))||Number(l.requestedQty)<1)throw badRequest('Each request line needs itemId and positive integer requestedQty');await getItem(l.itemId);}const request=await M.ResourceRequest.create({requestId:b.requestId||makeId('REQ'),departmentId:b.departmentId,eventId:b.eventId,venueId:b.venueId,requestedByStaffId:b.requestedByStaffId,lines:b.lines.map(l=>({itemId:l.itemId,requestedQty:Number(l.requestedQty)})),requiredAt:b.requiredAt?date(b.requiredAt,'requiredAt'):undefined,returnDeadline:b.returnDeadline?date(b.returnDeadline,'returnDeadline'):undefined,priority:b.priority||'normal',justification:b.justification,specialInstructions:b.specialInstructions,emergency:Boolean(b.emergency),status:'draft'});res.status(201).json({success:true,data:request});}));
logisticsApi.get('/logistics/requests/:id',requirePerm('inventory:read'),ah(async(req,res)=>{const request=await M.ResourceRequest.findOne({requestId:req.params.id}).lean();if(!request)throw notFound('No request');res.json({request});}));
logisticsApi.put('/logistics/requests/:id',requirePerm('inventory:request'),ah(async(req,res)=>{const request=await M.ResourceRequest.findOne({requestId:req.params.id});if(!request)throw notFound('No request');if(!['draft','rejected'].includes(request.status))throw conflict('Only draft or rejected requests can be edited');for(const k of ['departmentId','eventId','venueId','requiredAt','returnDeadline','priority','justification','specialInstructions'])if(req.body[k]!==undefined)request[k]=req.body[k];if(req.body.lines)request.lines=req.body.lines;await request.save();res.json({success:true,data:request});}));
logisticsApi.patch('/logistics/requests/:id/submit',requirePerm('inventory:request'),ah(async(req,res)=>{const r=await M.ResourceRequest.findOneAndUpdate({requestId:req.params.id,status:{$in:['draft','rejected']}},{status:'submitted'},{new:true});if(!r)throw conflict('Request cannot be submitted in its current state');res.json({success:true,data:r});}));
logisticsApi.patch('/logistics/requests/:id/approve',requirePerm('inventory:write'),ah(async(req,res)=>{const request=await M.ResourceRequest.findOne({requestId:req.params.id});if(!request)throw notFound('No request');if(!['submitted','under_review'].includes(request.status))throw conflict('Request must be submitted before approval');const requested=req.body?.approvedLines||request.lines.map(l=>({itemId:l.itemId,quantity:l.requestedQty,locationId:req.body?.locationId}));const results=[];const out=await runCommand({user:req.user,action:'LOGISTICS_REQUEST_APPROVED',entity:{type:'ResourceRequest',id:request.requestId},reason:req.body?.reason,risk:'low',event:'logistics.request.approved'},async(session)=>{for(const line of requested){const qty=Number(line.quantity);const reservation=await reserveLine({item:line.itemId,quantity:qty,locationId:line.locationId||req.body?.locationId,startAt:request.requiredAt,endAt:request.returnDeadline,user:req.user,requestId:request.requestId,reason:req.body?.reason,emergency:request.emergency,session});results.push(reservation.reservationId);const source=request.lines.find(x=>x.itemId===line.itemId);if(source)source.approvedQty=qty;}request.reservationIds=results;request.approvedBy=actor(req);request.status=results.length===request.lines.length?'reserved':'partially_approved';await request.save(session?{session}:{});return {summary:{requestId:request.requestId,reservations:results.length},result:{request,reservationIds:results}};});res.json({success:true,data:out});}));
logisticsApi.patch('/logistics/requests/:id/reject',requirePerm('inventory:write'),ah(async(req,res)=>{if(!req.body?.reason)throw badRequest('Rejection reason is required');const r=await M.ResourceRequest.findOneAndUpdate({requestId:req.params.id,status:{$in:['submitted','under_review']}},{status:'rejected',rejectionReason:req.body.reason,approvedBy:actor(req)},{new:true});if(!r)throw conflict('Request cannot be rejected in its current state');res.json({success:true,data:r});}));
logisticsApi.patch('/logistics/requests/:id/cancel',requirePerm('inventory:request'),ah(async(req,res)=>{const r=await M.ResourceRequest.findOne({requestId:req.params.id});if(!r)throw notFound('No request');if(['dispatched','fulfilled','completed'].includes(r.status))throw conflict('Dispatched resources must be returned before request completion');for(const rid of r.reservationIds){const reservation=await M.Reservation.findOne({reservationId:rid});if(reservation)await releaseReservation(reservation,req.user,null,'Request cancelled');}r.status='cancelled';await r.save();res.json({success:true,data:r});}));
logisticsApi.post('/logistics/reserve',requirePerm('inventory:write'),ah(async(req,res)=>{const b=req.body||{};const reservation=await runCommand({user:req.user,action:'LOGISTICS_STOCK_RESERVED',entity:{type:'InventoryItem',id:b.itemId},reason:b.reason,risk:'low',event:'logistics.reserved'},async(session)=>{const r=await reserveLine({item:b.itemId,quantity:b.quantity,locationId:b.locationId,startAt:b.startAt?date(b.startAt,'startAt'):undefined,endAt:b.endAt?date(b.endAt,'endAt'):undefined,user:req.user,reason:b.reason,emergency:b.emergency,session});return {summary:{reservationId:r.reservationId,quantity:r.quantity},result:r};});res.status(201).json({success:true,data:reservation});}));
logisticsApi.post('/logistics/reservations',requirePerm('inventory:write'),ah(async(req,res)=>{const b=req.body||{};const out=await runCommand({user:req.user,action:'LOGISTICS_STOCK_RESERVED',entity:{type:'InventoryItem',id:b.itemId},reason:b.reason,risk:'low',event:'logistics.reserved'},async(session)=>{const r=await reserveLine({item:b.itemId,quantity:b.quantity,locationId:b.locationId,startAt:b.startAt?date(b.startAt,'startAt'):undefined,endAt:b.endAt?date(b.endAt,'endAt'):undefined,user:req.user,reason:b.reason,emergency:b.emergency,session});return {summary:{reservationId:r.reservationId,quantity:r.quantity},result:r};});res.status(201).json({success:true,data:out});}));
logisticsApi.get('/logistics/reservations',requirePerm('inventory:read'),ah(async(req,res)=>{const q={};for(const k of ['itemId','locationId','requestId','status'])if(req.query[k])q[k]=req.query[k];await pageRows(M.Reservation,q,req,res,{createdAt:-1});}));
logisticsApi.get('/logistics/reservations/:id',requirePerm('inventory:read'),ah(async(req,res)=>{const reservation=await M.Reservation.findOne({reservationId:req.params.id}).lean();if(!reservation)throw notFound('No reservation');res.json({reservation});}));
logisticsApi.patch('/logistics/reservations/:id/cancel',requirePerm('inventory:write'),ah(async(req,res)=>{const out=await runCommand({user:req.user,action:'LOGISTICS_RESERVATION_CANCELLED',entity:{type:'Reservation',id:req.params.id},reason:req.body?.reason,risk:'low',event:'logistics.reservation.cancelled'},async(session)=>{const r=await M.Reservation.findOne({reservationId:req.params.id}).session(session);if(!r)throw notFound('No reservation');if(r.status!=='active')throw conflict('Reservation is not active');await releaseReservation(r,req.user,session,req.body?.reason||'Reservation cancelled');return {summary:{reservationId:r.reservationId},result:{reservation:r}};});res.json({success:true,data:out});}));
logisticsApi.patch('/logistics/reservations/:id/extend',requirePerm('inventory:write'),ah(async(req,res)=>{const endAt=date(req.body?.endAt,'endAt');const r=await M.Reservation.findOne({reservationId:req.params.id,status:'active'});if(!r)throw notFound('Active reservation not found');if(!req.body?.reason||req.body.reason.trim().length<5)throw badRequest('Extension requires a reason');if(r.endAt&&endAt<=r.endAt)throw badRequest('New endAt must extend the current reservation');if(r.assetIds.length){const conflictAsset=await M.Reservation.exists({reservationId:{$ne:r.reservationId},assetIds:{$in:r.assetIds},status:'active',startAt:{$lt:endAt},endAt:{$gt:r.endAt}});if(conflictAsset)throw conflict('Asset has an overlapping reservation');}r.endAt=endAt;r.reason=`${r.reason||''} | Extended: ${req.body.reason}`;await r.save();res.json({success:true,data:r});}));
for(const path of ['/logistics/availability','/logistics/availability/by-date'])logisticsApi.get(path,requirePerm('inventory:read'),ah(async(req,res)=>{const itemId=req.query.itemId;if(!itemId)throw badRequest('itemId is required');const startAt=req.query.startAt?date(req.query.startAt,'startAt'):undefined,endAt=req.query.endAt?date(req.query.endAt,'endAt'):undefined;res.json({success:true,data:{itemId,...await itemAvailability(itemId,{locationId:req.query.locationId,startAt,endAt})}});}));

// Dispatch / issue, custody and returns
logisticsApi.get('/logistics/dispatch/overdue',requirePerm('inventory:read'),ah(async(_req,res)=>res.json({rows:await M.Dispatch.find({status:{$in:['dispatched','partially_returned']},expectedReturnAt:{$lt:new Date()}}).sort({expectedReturnAt:1}).lean()})));
logisticsApi.get('/logistics/dispatch/by-event/:eventId',requirePerm('inventory:read'),ah(async(req,res)=>res.json({rows:await M.Dispatch.find({eventId:req.params.eventId}).sort({dispatchedAt:-1}).lean()})));
logisticsApi.get('/logistics/dispatch/by-custodian/:staffId',requirePerm('inventory:read'),ah(async(req,res)=>res.json({rows:await M.Dispatch.find({custodianStaffId:req.params.staffId,status:{$in:['dispatched','partially_returned']}}).lean()})));
logisticsApi.get('/logistics/dispatch',requirePerm('inventory:read'),ah(async(req,res)=>{const q={};for(const k of ['eventId','requestId','itemId','status','custodianStaffId'])if(req.query[k])q[k]=req.query[k];await pageRows(M.Dispatch,q,req,res,{dispatchedAt:-1});}));
logisticsApi.post('/logistics/dispatch',requirePerm('inventory:write'),ah(async(req,res)=>{const b=req.body||{};const reservation=await M.Reservation.findOne({reservationId:b.reservationId,status:'active'});if(!reservation)throw conflict('An active reservation is required before dispatch');const n=Number(b.quantity||reservation.quantity);if(!Number.isInteger(n)||n<1||n>reservation.quantity)throw badRequest('quantity must be between 1 and reserved quantity');const item=await getItem(reservation.itemId);if(['damaged','lost','retired','inactive'].includes(item.operationalStatus))throw conflict('Inventory item is not dispatchable');if(b.eventId&&!await M.Event.exists({eventId:b.eventId}))throw badRequest('Unknown eventId');if(b.venueId&&!await M.Venue.exists({venueId:b.venueId}))throw badRequest('Unknown venueId');const result=await runCommand({user:req.user,action:'LOGISTICS_DISPATCH_CREATED',entity:{type:'Reservation',id:reservation.reservationId},reason:b.notes,risk:'low',event:'logistics.dispatch.created'},async(session)=>{let assetIds=[];if(item.trackingType==='individual'){assetIds=reservation.assetIds.slice(0,n);if(assetIds.length!==n)throw conflict('Reserved assets do not match dispatch quantity');const updated=await M.Asset.updateMany({assetId:{$in:assetIds},status:'reserved'},{$set:{status:'issued',custodianStaffId:b.custodianStaffId,locationId:b.destinationLocationId||null}},session?{session}:{});if(updated.modifiedCount!==n)throw conflict('An asset is no longer reserved');reservation.assetIds=reservation.assetIds.filter(id=>!assetIds.includes(id));}else await changeBalance({itemId:item.itemId,itemName:item.item,locationId:reservation.locationId,fromState:'reserved',toState:'issued',quantity:n,user:req.user,reason:b.notes||'Dispatch',movementType:'dispatch',session,related:{relatedRequestId:reservation.requestId}});reservation.quantity-=n;if(reservation.quantity===0){reservation.status='dispatched';}await reservation.save(session?{session}:{});const dispatchId=makeId('DSP');const [dispatch]=await M.Dispatch.create([{dispatchId,requestId:reservation.requestId,reservationId:reservation.reservationId,itemId:item.itemId,assetIds,quantity:n,sourceLocationId:reservation.locationId,destinationLocationId:b.destinationLocationId,eventId:b.eventId||null,venueId:b.venueId||null,custodianStaffId:b.custodianStaffId,issuedTo:b.issuedTo||b.custodianStaffId,issuedBy:actor(req),expectedReturnAt:b.expectedReturnAt||reservation.endAt,conditionBefore:b.conditionBefore,notes:b.notes}],session?{session}:{});if(item.trackingType==='individual')await makeMovement(req,{item:item.item,itemId:item.itemId,assetId:assetIds[0],qty:n,from:{location:reservation.locationId,state:'reserved'},to:{location:b.destinationLocationId||reservation.locationId,state:'issued'},movementType:'dispatch',reason:b.notes,relatedRequestId:reservation.requestId,relatedDispatchId:dispatchId},session);if(reservation.requestId)await M.ResourceRequest.updateOne({requestId:reservation.requestId},{$set:{status:reservation.quantity?'partially_fulfilled':'dispatched'}},session?{session}:{});return {summary:{dispatchId,itemId:item.itemId,quantity:n},result:dispatch};});res.status(201).json({success:true,data:result});}));
logisticsApi.post('/logistics/dispatch/bulk',requirePerm('inventory:write'),ah(async(req,res)=>{const entries=req.body?.dispatches;if(!Array.isArray(entries)||!entries.length||entries.length>100)throw badRequest('dispatches must contain 1 to 100 entries');const results=[];for(const entry of entries){try{const r=await M.Reservation.findOne({reservationId:entry.reservationId,status:'active'});if(!r)throw conflict('Active reservation not found');const item=await getItem(r.itemId);const qty=Number(entry.quantity||r.quantity);if(item.trackingType==='individual'){const assetIds=r.assetIds.slice(0,qty);if(assetIds.length!==qty)throw conflict('Not enough reserved assets');await M.Asset.updateMany({assetId:{$in:assetIds},status:'reserved'},{$set:{status:'issued',custodianStaffId:entry.custodianStaffId}});r.assetIds=r.assetIds.slice(qty);}else await changeBalance({itemId:item.itemId,itemName:item.item,locationId:r.locationId,fromState:'reserved',toState:'issued',quantity:qty,user:req.user,reason:'Bulk dispatch',movementType:'dispatch'});r.quantity-=qty;if(!r.quantity)r.status='dispatched';await r.save();const [d]=await M.Dispatch.create([{dispatchId:makeId('DSP'),requestId:r.requestId,reservationId:r.reservationId,itemId:r.itemId,assetIds:item.trackingType==='individual'?r.assetIds:[],quantity:qty,sourceLocationId:r.locationId,destinationLocationId:entry.destinationLocationId,eventId:entry.eventId,venueId:entry.venueId,custodianStaffId:entry.custodianStaffId,issuedTo:entry.issuedTo||entry.custodianStaffId,issuedBy:actor(req),expectedReturnAt:entry.expectedReturnAt}]);results.push(d);}catch(e){results.push({error:e.message,reservationId:entry.reservationId});}}res.status(201).json({success:true,data:{results,dispatched:results.filter(x=>!x.error).length,exceptions:results.filter(x=>x.error)}});}));
