logisticsApi.post('/logistics/return',requirePerm('inventory:write'),ah(async(req,res)=>{const b=req.body||{};const d=await M.Dispatch.findOne({dispatchId:b.dispatchId});if(!d)throw notFound('No dispatch');if(['returned','closed'].includes(d.status))throw conflict('Dispatch has already been reconciled');const returned=Number(b.returnedQty||0),missing=Number(b.missingQty||0),damaged=Number(b.damagedQty||0);if(!Number.isInteger(returned)||!Number.isInteger(missing)||!Number.isInteger(damaged)||returned<0||missing<0||damaged<0||damaged>returned)throw badRequest('Return quantities must be non-negative integers and damagedQty cannot exceed returnedQty');const outstanding=d.quantity-(d.reconciledQty||0);if(returned+missing>outstanding)throw conflict('Return exceeds outstanding dispatch quantity',{outstanding});const item=await getItem(d.itemId);const result=await runCommand({user:req.user,action:'LOGISTICS_RETURN_RECORDED',entity:{type:'Dispatch',id:d.dispatchId},reason:b.inspectionNotes,risk:'low',event:'logistics.return.recorded'},async(session)=>{const good=returned-damaged;if(item.trackingType==='individual'){const returnedIds=b.assetIds||[];if(returnedIds.length!==returned)throw badRequest('assetIds must match returnedQty for individual assets');if(returnedIds.some(id=>!d.assetIds.includes(id)))throw badRequest('Returned asset is not part of this dispatch');const damagedIds=new Set(b.damagedAssetIds||[]);await M.Asset.updateMany({assetId:{$in:returnedIds},status:'issued'},{$set:{status:'available',locationId:d.sourceLocationId,custodianStaffId:null}},session?{session}:{});if(damagedIds.size)await M.Asset.updateMany({assetId:{$in:[...damagedIds]}},{$set:{status:'damaged'}},session?{session}:{});if(missing)await M.Asset.updateMany({assetId:{$in:b.missingAssetIds||[]},status:'issued'},{$set:{status:'missing'}},session?{session}:{});}else{if(good)await changeBalance({itemId:d.itemId,itemName:item.item,locationId:d.sourceLocationId,fromState:'issued',toState:'available',quantity:good,user:req.user,reason:'Return',movementType:'return',session,related:{relatedDispatchId:d.dispatchId}});if(damaged)await changeBalance({itemId:d.itemId,itemName:item.item,locationId:d.sourceLocationId,fromState:'issued',toState:'damaged',quantity:damaged,user:req.user,reason:'Damaged on return',movementType:'damaged',session,related:{relatedDispatchId:d.dispatchId}});if(missing)await changeBalance({itemId:d.itemId,itemName:item.item,locationId:d.sourceLocationId,fromState:'issued',toState:'missing',quantity:missing,user:req.user,reason:'Missing at reconciliation',movementType:'missing',session,related:{relatedDispatchId:d.dispatchId}});}d.returnedQty+=returned;d.reconciledQty=(d.reconciledQty||0)+returned+missing;d.missingQty=(d.missingQty||0)+missing;const reconciled=d.reconciledQty;d.status=reconciled>=d.quantity?'returned':'partially_returned';if(d.status==='returned')d.actualReturnAt=new Date();await d.save(session?{session}:{});const returnId=makeId('RET');const [record]=await M.ReturnRecord.create([{returnId,dispatchId:d.dispatchId,itemId:d.itemId,assetIds:b.assetIds||[],expectedQty:outstanding,returnedQty:returned,missingQty:missing,damagedQty:damaged,conditionAfter:b.conditionAfter,returnedBy:b.returnedBy,receivedBy:actor(req),inspectionNotes:b.inspectionNotes,inspectionStatus:'verified'}],session?{session}:{});return {summary:{returnId,dispatchId:d.dispatchId,returned,missing,damaged},result:{record,dispatch:d}};});res.json({success:true,data:result});}));
logisticsApi.post('/logistics/return/bulk',requirePerm('inventory:write'),ah(async(req,res)=>{const list=req.body?.returns;if(!Array.isArray(list)||!list.length||list.length>100)throw badRequest('returns must contain 1 to 100 entries');const results=[];for(const r of list){try{const d=await M.Dispatch.findOne({dispatchId:r.dispatchId});if(!d)throw notFound('No dispatch');const n=Number(r.returnedQty||0),miss=Number(r.missingQty||0),dam=Number(r.damagedQty||0);if(n+miss>d.quantity-(d.reconciledQty||0)||dam>n)throw conflict('Return quantities exceed outstanding amount');const item=await getItem(d.itemId);if(item.trackingType!=='individual'){if(n-dam)await changeBalance({itemId:d.itemId,itemName:item.item,locationId:d.sourceLocationId,fromState:'issued',toState:'available',quantity:n-dam,user:req.user,reason:'Bulk return',movementType:'return'});if(dam)await changeBalance({itemId:d.itemId,itemName:item.item,locationId:d.sourceLocationId,fromState:'issued',toState:'damaged',quantity:dam,user:req.user,reason:'Bulk damaged return',movementType:'damaged'});if(miss)await changeBalance({itemId:d.itemId,itemName:item.item,locationId:d.sourceLocationId,fromState:'issued',toState:'missing',quantity:miss,user:req.user,reason:'Bulk missing return',movementType:'missing'});}d.returnedQty+=n;d.reconciledQty=(d.reconciledQty||0)+n+miss;d.missingQty=(d.missingQty||0)+miss;d.status=d.reconciledQty>=d.quantity?'returned':'partially_returned';await d.save();const [rec]=await M.ReturnRecord.create([{returnId:makeId('RET'),dispatchId:d.dispatchId,itemId:d.itemId,expectedQty:d.quantity,returnedQty:n,missingQty:miss,damagedQty:dam,receivedBy:actor(req),inspectionStatus:'verified'}]);results.push(rec);}catch(e){results.push({dispatchId:r.dispatchId,error:e.message});}}res.json({success:true,data:{results,exceptions:results.filter(x=>x.error)}});}));
