logisticsApi.post('/logistics/incidents',requirePerm('inventory:write'),ah(async(req,res)=>{const b=req.body||{};if(!b.incidentType||!b.description)throw badRequest('incidentType and description are required');if(b.assetId){const a=await M.Asset.findOne({assetId:b.assetId});if(!a)throw notFound('No asset');if(b.incidentType==='missing'||b.incidentType==='loss'||b.incidentType==='theft')a.status='missing';else if(['damage','malfunction','unusable'].includes(b.incidentType))a.status='damaged';await a.save();}else if(b.itemId&&b.quantity&&['missing','loss','damage','unusable'].includes(b.incidentType)){const item=await getItem(b.itemId);await changeBalance({itemId:b.itemId,itemName:item.item,locationId:b.locationId,fromState:b.fromState||'available',toState:b.incidentType==='missing'||b.incidentType==='loss'?'missing':'damaged',quantity:Number(b.quantity),user:req.user,reason:b.description,movementType:b.incidentType==='missing'?'missing':'damaged'});}const incident=await M.DamageLossIncident.create({...b,incidentId:b.incidentId||makeId('INC'),reportedBy:actor(req)});res.status(201).json({success:true,data:incident});}));
