logisticsApi.patch('/logistics/incidents/:id/resolve',requirePerm('inventory:write'),ah(async(req,res)=>{if(!req.body?.resolution)throw badRequest('resolution is required');const incident=await M.DamageLossIncident.findOne({incidentId:req.params.id});if(!incident)throw notFound('No incident');incident.resolution=req.body.resolution;incident.resolvedBy=actor(req);incident.resolvedAt=new Date();incident.status=req.body.writtenOff?'written_off':'resolved';if(incident.assetId&&req.body.recovered){await M.Asset.updateOne({assetId:incident.assetId},{status:'available',locationId:req.body.locationId});}incident.save();res.json({incident});}));
