logisticsApi.patch('/logistics/maintenance/:id/complete',requirePerm('inventory:write'),ah(async(req,res)=>{if(!req.body?.inspectionResult)throw badRequest('inspectionResult is required');const task=await M.MaintenanceTask.findOne({maintenanceId:req.params.id,status:'in_progress'});if(!task)throw conflict('Task is not in progress');task.status='completed';task.completedAt=new Date();task.inspectionResult=req.body.inspectionResult;task.cost=Number(req.body.cost||0);task.nextMaintenanceDate=req.body.nextMaintenanceDate;await task.save();if(task.assetId)await M.Asset.updateOne({assetId:task.assetId,status:'maintenance'},{$set:{status:req.body.operational===false?'damaged':'available',lastInspection:new Date(),nextMaintenanceDate:task.nextMaintenanceDate},$push:{maintenanceHistory:{maintenanceId:task.maintenanceId,completedAt:task.completedAt,result:task.inspectionResult,cost:task.cost}}});res.json({task});}));

