logisticsApi.get('/logistics/transfers',requirePerm('inventory:read'),ah(async(req,res)=>{const q={};if(req.query.status)q.status=req.query.status;await pageRows(M.StockTransfer,q,req,res,{requestedAt:-1});}));
logisticsApi.post('/logistics/transfers',requirePerm('inventory:write'),ah(async(req,res)=>{const b=req.body||{};const n=Number(b.quantity);if(!b.itemId||!b.fromLocationId||!b.toLocationId||b.fromLocationId===b.toLocationId||!Number.isInteger(n)||n<1)throw badRequest('itemId, distinct source/destination locations and positive integer quantity are required');await getItem(b.itemId);for(const id of [b.fromLocationId,b.toLocationId])if(!await M.Location.exists({locationId:id,status:'active'}))throw badRequest(`Location ${id} is not active`);const transfer=await M.StockTransfer.create({transferId:b.transferId||makeId('TRF'),itemId:b.itemId,quantity:n,fromLocationId:b.fromLocationId,toLocationId:b.toLocationId,requestedBy:actor(req),reason:b.reason});res.status(201).json({success:true,data:transfer});}));
logisticsApi.get('/logistics/transfers/:id',requirePerm('inventory:read'),ah(async(req,res)=>{const t=await M.StockTransfer.findOne({transferId:req.params.id}).lean();if(!t)throw notFound('No transfer');res.json({transfer:t});}));
logisticsApi.patch('/logistics/transfers/:id/approve',requirePerm('inventory:write'),ah(async(req,res)=>{const t=await M.StockTransfer.findOne({transferId:req.params.id,status:'pending'});if(!t)throw conflict('Transfer is not pending');const item=await getItem(t.itemId);const out=await runCommand({user:req.user,action:'LOGISTICS_TRANSFER_APPROVED',entity:{type:'StockTransfer',id:t.transferId},reason:req.body?.reason,risk:'low',event:'logistics.transfer.approved'},async(session)=>{if(item.trackingType==='individual'){const assets=await M.Asset.find({itemId:t.itemId,locationId:t.fromLocationId,status:'available'}).limit(t.quantity).session(session).lean();if(assets.length!==t.quantity)throw conflict('Insufficient available assets at source');t.assetIds=assets.map(a=>a.assetId);const upd=await M.Asset.updateMany({assetId:{$in:t.assetIds},status:'available'},{$set:{status:'inactive'}},session?{session}:{});if(upd.modifiedCount!==t.quantity)throw conflict('Assets changed during transfer');}else await changeBalance({itemId:t.itemId,itemName:item.item,locationId:t.fromLocationId,fromState:'available',toState:'in_transit',quantity:t.quantity,user:req.user,reason:t.reason||'Transfer approved',movementType:'transfer_out',session});t.status='in_transit';t.approvedBy=actor(req);await t.save(session?{session}:{});return {summary:{transferId:t.transferId,quantity:t.quantity},result:t};});res.json({success:true,data:out});}));
logisticsApi.patch('/logistics/transfers/:id/receive',requirePerm('inventory:write'),ah(async(req,res)=>{const t=await M.StockTransfer.findOne({transferId:req.params.id,status:'in_transit'});if(!t)throw conflict('Transfer must be in transit');const n=Number(req.body?.receivedQty??t.quantity);if(!Number.isInteger(n)||n<0||n>t.quantity)throw badRequest('receivedQty must be between zero and transferred quantity');const item=await getItem(t.itemId);const out=await runCommand({user:req.user,action:'LOGISTICS_TRANSFER_RECEIVED',entity:{type:'StockTransfer',id:t.transferId},reason:req.body?.discrepancy,risk:'low',event:'logistics.transfer.received'},async(session)=>{if(item.trackingType==='individual'){const ids=t.assetIds.slice(0,n);await M.Asset.updateMany({assetId:{$in:ids},status:'inactive'},{$set:{status:'available',locationId:t.toLocationId}},session?{session}:{});}else{if(t.quantity)await changeBalance({itemId:t.itemId,itemName:item.item,locationId:t.fromLocationId,fromState:'in_transit',toState:null,quantity:t.quantity,user:req.user,reason:'Transfer received',movementType:'transfer_out',session});if(n)await changeBalance({itemId:t.itemId,itemName:item.item,locationId:t.toLocationId,fromState:null,toState:'available',quantity:n,user:req.user,reason:'Transfer received',movementType:'transfer_in',session});if(n<t.quantity)await changeBalance({itemId:t.itemId,itemName:item.item,locationId:t.fromLocationId,fromState:null,toState:'needs_check',quantity:t.quantity-n,user:req.user,reason:'Transfer discrepancy',movementType:'adjustment',session});}t.receivedQty=n;t.receivedBy=actor(req);t.receivedAt=new Date();t.discrepancy=req.body?.discrepancy;t.status=n===t.quantity?'received':'disputed';await t.save(session?{session}:{});return {summary:{transferId:t.transferId,expected:t.quantity,received:n},result:t};});res.json({success:true,data:out});}));
logisticsApi.get('/logistics/movements',requirePerm('inventory:read'),ah(async(req,res)=>{const q={};if(req.query.itemId)q.itemId=req.query.itemId;if(req.query.movementType)q.movementType=req.query.movementType;await pageRows(M.StockMovement,q,req,res,{at:-1});}));
