// Purchasing: supplier remains owned by the Vendors module.
logisticsApi.get('/logistics/purchase-orders',requirePerm('inventory:read'),ah(async(req,res)=>{const q={};if(req.query.status)q.status=req.query.status;await pageRows(M.PurchaseOrder,q,req,res,{createdAt:-1});}));
logisticsApi.post('/logistics/purchase-orders',requirePerm('inventory:write'),ah(async(req,res)=>{const b=req.body||{};if(!Array.isArray(b.lines)||!b.lines.length)throw badRequest('Purchase order lines are required');if(b.supplierId&&!await M.Vendor.exists({vendorId:b.supplierId}))throw badRequest('supplierId must reference an existing vendor');let total=0;for(const l of b.lines){if(!Number.isInteger(Number(l.quantity))||Number(l.quantity)<1||Number(l.unitPrice)<0)throw badRequest('Purchase quantities and prices must be valid');await getItem(l.itemId);total+=Number(l.quantity)*Number(l.unitPrice);}const po=await M.PurchaseOrder.create({poNumber:b.poNumber||makeId('PO'),supplierId:b.supplierId,lines:b.lines,tax:Number(b.tax||0),totalCost:total+Number(b.tax||0),deliveryLocationId:b.deliveryLocationId,expectedDeliveryAt:b.expectedDeliveryAt,requestedBy:actor(req),notes:b.notes});res.status(201).json({success:true,data:po});}));
logisticsApi.get('/logistics/purchase-orders/:id',requirePerm('inventory:read'),ah(async(req,res)=>{const po=await M.PurchaseOrder.findOne({poNumber:req.params.id}).lean();if(!po)throw notFound('No purchase order');res.json({purchaseOrder:po});}));
logisticsApi.patch('/logistics/purchase-orders/:id/approve',requirePerm('inventory:write'),ah(async(req,res)=>{const po=await M.PurchaseOrder.findOneAndUpdate({poNumber:req.params.id,approvalStatus:'pending',status:'open'},{$set:{approvalStatus:'approved',approvedBy:actor(req)}},{new:true});if(!po)throw conflict('Purchase order is not pending approval');res.json({success:true,data:po});}));
logisticsApi.patch('/logistics/purchase-orders/:id/cancel',requirePerm('inventory:write'),ah(async(req,res)=>{const po=await M.PurchaseOrder.findOneAndUpdate({poNumber:req.params.id,status:{$in:['open','partial']}},{$set:{status:'cancelled'}},{new:true});if(!po)throw conflict('Purchase order cannot be cancelled');res.json({success:true,data:po});}));
logisticsApi.get('/logistics/goods-receipts',requirePerm('inventory:read'),ah(async(req,res)=>{const q={};if(req.query.poNumber)q.poNumber=req.query.poNumber;await pageRows(M.GoodsReceipt,q,req,res,{receivedAt:-1});}));
logisticsApi.post('/logistics/goods-receipts',requirePerm('inventory:write'),ah(async(req,res)=>{const b=req.body||{};const po=await M.PurchaseOrder.findOne({poNumber:b.poNumber,approvalStatus:'approved',status:{$in:['open','partial']}});if(!po)throw conflict('An approved open purchase order is required');if(b.idempotencyKey&&await M.GoodsReceipt.exists({idempotencyKey:b.idempotencyKey}))throw conflict('Receipt idempotency key already processed');const lines=b.lines||[];if(!lines.length)throw badRequest('Receipt lines are required');const result=await runCommand({user:req.user,action:'LOGISTICS_GOODS_RECEIVED',entity:{type:'PurchaseOrder',id:po.poNumber},reason:b.discrepancyNotes,risk:'low',event:'logistics.goods.received'},async(session)=>{for(const l of lines){const ordered=po.lines.find(x=>x.itemId===l.itemId);if(!ordered)throw badRequest(`Item ${l.itemId} is not on this purchase order`);const received=Number(l.actualQty),damaged=Number(l.damagedQty||0),rejected=Number(l.rejectedQty||0);if(!Number.isInteger(received)||received<0||damaged+rejected>received)throw badRequest('Receipt quantities are invalid');const usable=received-damaged-rejected;if(usable)await changeBalance({itemId:l.itemId,itemName:(await getItem(l.itemId)).item,locationId:po.deliveryLocationId,fromState:null,toState:'available',quantity:usable,user:req.user,reason:'PO goods receipt',movementType:'purchase_received',session});if(damaged)await changeBalance({itemId:l.itemId,itemName:(await getItem(l.itemId)).item,locationId:po.deliveryLocationId,fromState:null,toState:'damaged',quantity:damaged,user:req.user,reason:'Damaged goods received',movementType:'damaged',session});}const [receipt]=await M.GoodsReceipt.create([{receiptId:makeId('GR'),poNumber:po.poNumber,lines,receivedBy:actor(req),inspectionStatus:'recorded',discrepancyNotes:b.discrepancyNotes,idempotencyKey:b.idempotencyKey}],session?{session}:{});po.status='partial';await po.save(session?{session}:{});return {summary:{receiptId:receipt.receiptId,poNumber:po.poNumber},result:receipt};});res.status(201).json({success:true,data:result});}));

// Stocktake and adjustment workflow. Variances are applied only after manager approval.
logisticsApi.get('/logistics/audits',requirePerm('inventory:read'),ah(async(req,res)=>{const q={};if(req.query.locationId)q.locationId=req.query.locationId;if(req.query.status)q.status=req.query.status;await pageRows(M.InventoryAudit,q,req,res,{createdAt:-1});}));
logisticsApi.post('/logistics/audits',requirePerm('inventory:write'),ah(async(req,res)=>{const b=req.body||{};if(!b.locationId||!await M.Location.exists({locationId:b.locationId}))throw badRequest('Existing locationId is required');const audit=await M.InventoryAudit.create({auditId:b.auditId||makeId('AUD'),locationId:b.locationId,categoryId:b.categoryId,status:'counting',createdBy:actor(req)});const balances=await M.StockBalance.find({location:b.locationId}).lean();const expected=new Map();for(const x of balances){const catalog=await M.InventoryItem.findOne({$or:[{itemId:x.item},{item:x.item},{itemName:x.item}]}).select('itemId').lean();const itemId=catalog?.itemId||x.item;expected.set(itemId,(expected.get(itemId)||0)+(x.state==='available'?x.qty:0));}for(const [itemId,expectedQty] of expected)await M.InventoryAuditCount.create({auditId:audit.auditId,itemId,expectedQty,countedQty:null});res.status(201).json({audit,expectedLines:expected.size});}));
logisticsApi.get('/logistics/audits/:id',requirePerm('inventory:read'),ah(async(req,res)=>{const audit=await M.InventoryAudit.findOne({auditId:req.params.id}).lean();if(!audit)throw notFound('No audit');res.json({audit,counts:await M.InventoryAuditCount.find({auditId:audit.auditId}).lean()});}));
logisticsApi.post('/logistics/audits/:id/counts',requirePerm('inventory:write'),ah(async(req,res)=>{const audit=await M.InventoryAudit.findOne({auditId:req.params.id,status:{$in:['counting','draft']}});if(!audit)throw conflict('Audit is not open for counting');const lines=req.body?.counts;if(!Array.isArray(lines)||!lines.length)throw badRequest('counts array is required');const saved=[];for(const x of lines){const countedQty=Number(x.countedQty);if(!x.itemId||!Number.isInteger(countedQty)||countedQty<0)throw badRequest('Each count requires itemId and non-negative integer countedQty');const existing=await M.InventoryAuditCount.findOne({auditId:audit.auditId,itemId:x.itemId});if(existing){existing.countedQty=countedQty;existing.damagedQty=Number(x.damagedQty||0);existing.missingQty=Number(x.missingQty||0);existing.notes=x.notes;await existing.save();saved.push(existing);}else saved.push(await M.InventoryAuditCount.create({auditId:audit.auditId,itemId:x.itemId,expectedQty:0,countedQty,damagedQty:Number(x.damagedQty||0),missingQty:Number(x.missingQty||0),notes:x.notes}));}res.json({success:true,data:saved});}));
logisticsApi.post('/logistics/audits/:id/submit',requirePerm('inventory:write'),ah(async(req,res)=>{const a=await M.InventoryAudit.findOneAndUpdate({auditId:req.params.id,status:'counting'},{$set:{status:'submitted',submittedBy:actor(req),submittedAt:new Date()}},{new:true});if(!a)throw conflict('Audit cannot be submitted');res.json({audit:a});}));
logisticsApi.get('/logistics/audits/:id/discrepancies',requirePerm('inventory:read'),ah(async(req,res)=>{const counts=await M.InventoryAuditCount.find({auditId:req.params.id,$expr:{$ne:['$expectedQty','$countedQty']}}).lean();res.json({discrepancies:counts});}));
logisticsApi.patch('/logistics/audits/:id/approve',requirePerm('inventory:write'),ah(async(req,res)=>{if(!req.body?.reason||req.body.reason.trim().length<5)throw badRequest('Audit approval reason is required');const a=await M.InventoryAudit.findOne({auditId:req.params.id,status:'submitted'});if(!a)throw conflict('Audit must be submitted before approval');const counts=await M.InventoryAuditCount.find({auditId:a.auditId});const result=await runCommand({user:req.user,action:'LOGISTICS_AUDIT_APPROVED',entity:{type:'InventoryAudit',id:a.auditId},reason:req.body.reason,risk:'medium',event:'logistics.audit.approved'},async(session)=>{for(const c of counts){if(c.countedQty==null)throw badRequest(`Count ${c.itemId} is incomplete`);const delta=c.countedQty-c.expectedQty;if(delta>0)await changeBalance({itemId:c.itemId,itemName:(await getItem(c.itemId)).item,locationId:a.locationId,fromState:null,toState:'available',quantity:delta,user:req.user,reason:req.body.reason,movementType:'adjustment',session});if(delta<0)await changeBalance({itemId:c.itemId,itemName:(await getItem(c.itemId)).item,locationId:a.locationId,fromState:'available',toState:null,quantity:-delta,user:req.user,reason:req.body.reason,movementType:'adjustment',session});}a.status='approved';a.approvedBy=actor(req);a.approvedAt=new Date();a.reason=req.body.reason;await a.save(session?{session}:{});return {summary:{auditId:a.auditId,adjustments:counts.length},result:{audit:a}};});res.json({success:true,data:result});}));

// Reorder suggestions and actual-record analytics
logisticsApi.get('/logistics/reorder-suggestions',requirePerm('inventory:read'),ah(async(_req,res)=>{const items=await M.InventoryItem.find({}).lean();const suggestions=[];for(const item of items){const bal=await M.StockBalance.find({item:{$in:[item.itemId,item.item,item.itemName].filter(Boolean)}}).lean();const byLoc=new Map();for(const b of bal)byLoc.set(b.location,(byLoc.get(b.location)||0)+ (b.state==='available'?b.qty:0));for(const [locationId,qty] of byLoc){if(qty<=Number(item.reorderThreshold||0)){let s=await M.ReorderSuggestion.findOne({itemId:item.itemId,locationId,status:'open'});if(!s)s=await M.ReorderSuggestion.create({suggestionId:makeId('RDR'),itemId:item.itemId,locationId,usableQty:qty,reservedQty:summarizeStock(bal.filter(b=>b.location===locationId)).reserved,reorderThreshold:item.reorderThreshold,suggestedQty:Math.max(Number(item.minimumStock||0),Number(item.reorderThreshold||0)-qty)});suggestions.push(s.toObject());}}}res.json({suggestions});}));
logisticsApi.post('/logistics/reorder-suggestions/:id/approve',requirePerm('inventory:write'),ah(async(req,res)=>{const s=await M.ReorderSuggestion.findOneAndUpdate({suggestionId:req.params.id,status:'open'},{$set:{status:'approved',approvedBy:actor(req)}},{new:true});if(!s)throw notFound('Open suggestion not found');res.json({success:true,data:s,note:'Create a purchase order separately; suggestions never procure automatically.'});}));
logisticsApi.get('/logistics/stock-forecast',requirePerm('inventory:read'),ah(async(_req,res)=>{const requests=await M.ResourceRequest.find({status:{$in:['submitted','under_review','approved','partially_approved','reserved']}}).lean();const by={};for(const r of requests)for(const l of r.lines)by[l.itemId]=(by[l.itemId]||0)+Math.max(0,l.requestedQty-(l.approvedQty||0));const items=await M.InventoryItem.find({}).lean();const rows=[];for(const item of items){const stock=summarizeStock(await M.StockBalance.find({item:{$in:[item.itemId,item.item,item.itemName].filter(Boolean)}}).lean());rows.push({itemId:item.itemId,available:stock.available,reserved:stock.reserved,futureDemand:by[item.itemId]||0,projected:stock.available-(by[item.itemId]||0)});}res.json({rows});}));
logisticsApi.get('/logistics/alerts',requirePerm('inventory:read'),ah(async(req,res)=>{const items=await M.InventoryItem.find({}).lean();const alerts=[];for(const i of items){const s=summarizeStock(await M.StockBalance.find({item:{$in:[i.itemId,i.item,i.itemName].filter(Boolean)}}).lean());if(s.available<=i.reorderThreshold)alerts.push({code:'LOW_STOCK',itemId:i.itemId,available:s.available,reorderThreshold:i.reorderThreshold,criticality:i.criticality});if(s.damaged)alerts.push({code:'DAMAGED_STOCK',itemId:i.itemId,quantity:s.damaged});if(s.missing)alerts.push({code:'MISSING_STOCK',itemId:i.itemId,quantity:s.missing});}res.json({alerts});}));

logisticsApi.get('/logistics/dashboard',requirePerm('inventory:read'),ah(async(_req,res)=>{const [items,balances,assets,requests,dispatches,incidents,maintenance,purchases]=await Promise.all([M.InventoryItem.find({}).lean(),M.StockBalance.find({}).lean(),M.Asset.find({}).lean(),M.ResourceRequest.countDocuments({status:{$in:['submitted','under_review']}}),M.Dispatch.countDocuments({status:{$in:['dispatched','partially_returned']}}),M.DamageLossIncident.countDocuments({status:{$in:['open','investigating','maintenance']}}),M.MaintenanceTask.countDocuments({status:{$in:['scheduled','in_progress','overdue']}}),M.PurchaseOrder.aggregate([{$match:{approvalStatus:'approved'}},{$group:{_id:null,expenditure:{$sum:'$totalCost'}}}])]);const stock=summarizeStock(balances);res.json({items:items.length,assets:assets.length,stock,requestsPending:requests,dispatchesOutstanding:dispatches,incidentsOpen:incidents,maintenanceOpen:maintenance,procurementApprovedINR:purchases[0]?.expenditure||0,inventoryValue:items.reduce((s,i)=>s+Number(i.unitPurchaseCost||0)*(balances.filter(b=>b.item===i.itemId||b.item===i.item||b.item===i.itemName).reduce((n,b)=>n+b.qty,0)),0)});}));
logisticsApi.get('/logistics/analytics/usage',requirePerm('inventory:read'),ah(async(req,res)=>{const match={};if(req.query.from||req.query.to)match.dispatchedAt={...(req.query.from?{$gte:date(req.query.from,'from')}:{}),...(req.query.to?{$lte:date(req.query.to,'to')}:{})};const rows=await M.Dispatch.aggregate([{$match:match},{$group:{_id:'$itemId',dispatches:{$sum:1},quantity:{$sum:'$quantity'}}},{$sort:{quantity:-1}},{$limit:100}]);res.json({rows});}));
logisticsApi.get('/logistics/analytics/utilization',requirePerm('inventory:read'),ah(async(_req,res)=>{const [assets,dispatches]=await Promise.all([M.Asset.countDocuments({}),M.Asset.countDocuments({status:'issued'})]);res.json({individualAssets:assets,issuedAssets:dispatches,utilizationRate:assets?dispatches/assets:0});}));
logisticsApi.get('/logistics/analytics/costs',requirePerm('inventory:read'),ah(async(_req,res)=>{const [items,purchases,maint]=await Promise.all([M.InventoryItem.find({}).lean(),M.PurchaseOrder.aggregate([{$match:{approvalStatus:'approved'}},{$group:{_id:null,total:{$sum:'$totalCost'}}}]),M.MaintenanceTask.aggregate([{$match:{status:'completed'}},{$group:{_id:null,total:{$sum:'$cost'}}}])]);res.json({inventoryValue:items.reduce((s,i)=>s+Number(i.currentBookValue??i.unitPurchaseCost??0),0),procurementExpenditure:purchases[0]?.total||0,maintenanceExpenditure:maint[0]?.total||0});}));
logisticsApi.get('/logistics/analytics/damage-loss',requirePerm('inventory:read'),ah(async(_req,res)=>{const rows=await M.DamageLossIncident.aggregate([{$group:{_id:{type:'$incidentType',status:'$status'},count:{$sum:1},estimatedCost:{$sum:'$estimatedCost'}}}]);res.json({rows});}));
for(const [route,key] of [['by-event','eventId'],['by-department','departmentId']])logisticsApi.get(`/logistics/analytics/${route}`,requirePerm('inventory:read'),ah(async(req,res)=>{const requests=await M.ResourceRequest.find({[key]:{$ne:null}}).lean();const ids=[...new Set(requests.map(r=>r[key]))];const rows=ids.map(id=>({[key]:id,requests:requests.filter(r=>r[key]===id).length,requestedQty:requests.filter(r=>r[key]===id).reduce((s,r)=>s+r.lines.reduce((n,l)=>n+l.requestedQty,0),0)}));res.json({rows});}));

// Scanning resolves an asset ID; the actual state changes still use reservation and dispatch records.
logisticsApi.post('/logistics/assets/scan/dispatch',requirePerm('inventory:write'),ah(async(req,res)=>{const b=req.body||{};const asset=await M.Asset.findOne({$or:[{assetTag:b.code},{qrCode:b.code},{barcode:b.code},{assetId:b.code}]});if(!asset)throw notFound('Scanned asset was not found');if(asset.status!=='available')throw conflict(`Asset status is ${asset.status}`);if(b.eventId&&!await M.Event.exists({eventId:b.eventId}))throw badRequest('Unknown eventId');if(b.venueId&&!await M.Venue.exists({venueId:b.venueId}))throw badRequest('Unknown venueId');const result=await runCommand({user:req.user,action:'LOGISTICS_SCANNED_ASSET_DISPATCHED',entity:{type:'Asset',id:asset.assetId},reason:b.reason,risk:'low',event:'logistics.dispatch.scanned'},async(session)=>{asset.status='issued';asset.custodianStaffId=b.custodianStaffId;asset.locationId=b.destinationLocationId||asset.locationId;await asset.save(session?{session}:{});const [d]=await M.Dispatch.create([{dispatchId:makeId('DSP'),itemId:asset.itemId,assetIds:[asset.assetId],quantity:1,sourceLocationId:b.sourceLocationId||asset.locationId,destinationLocationId:b.destinationLocationId,eventId:b.eventId,venueId:b.venueId,custodianStaffId:b.custodianStaffId,issuedTo:b.issuedTo||b.custodianStaffId,issuedBy:actor(req),expectedReturnAt:b.expectedReturnAt,conditionBefore:asset.condition}],session?{session}:{});await makeMovement(req,{item:asset.itemId,itemId:asset.itemId,assetId:asset.assetId,qty:1,from:{location:b.sourceLocationId||asset.locationId,state:'available'},to:{location:b.destinationLocationId||asset.locationId,state:'issued'},movementType:'dispatch',reason:b.reason,relatedDispatchId:d.dispatchId},session);return {summary:{dispatchId:d.dispatchId,assetId:asset.assetId},result:d};});res.status(201).json({success:true,data:result});}));
logisticsApi.post('/logistics/assets/scan/return',requirePerm('inventory:write'),ah(async(req,res)=>{const b=req.body||{};const d=await M.Dispatch.findOne({dispatchId:b.dispatchId,status:{$in:['dispatched','partially_returned']}});if(!d)throw notFound('Open dispatch not found');const asset=await M.Asset.findOne({$or:[{assetTag:b.code},{qrCode:b.code},{barcode:b.code},{assetId:b.code}]});if(!asset||!d.assetIds.includes(asset.assetId))throw conflict('Scanned asset does not belong to this open dispatch');const status=b.conditionAfter==='damaged'?'damaged':'available';asset.status=status;asset.locationId=d.sourceLocationId;asset.custodianStaffId=null;asset.condition=b.conditionAfter||asset.condition;await asset.save();d.returnedQty=Math.min(d.quantity,d.returnedQty+1);if(d.returnedQty>=d.quantity)d.status='returned';await d.save();const [r]=await M.ReturnRecord.create([{returnId:makeId('RET'),dispatchId:d.dispatchId,itemId:d.itemId,assetIds:[asset.assetId],expectedQty:1,returnedQty:1,damagedQty:status==='damaged'?1:0,conditionAfter:asset.condition,receivedBy:actor(req),inspectionStatus:'verified'}]);await makeMovement(req,{item:d.itemId,itemId:d.itemId,assetId:asset.assetId,qty:1,from:{location:d.destinationLocationId||d.sourceLocationId,state:'issued'},to:{location:d.sourceLocationId,state:status},movementType:status==='damaged'?'damaged':'return',reason:b.notes,relatedDispatchId:d.dispatchId,relatedReturnId:r.returnId});res.json({success:true,data:{asset,returnRecord:r}});}));

// Preview only; approval and execution are separate operations. These events feed the shared event bus for Ripple consumers.
logisticsApi.post('/logistics/simulate-disruption',requirePerm('disruptions:preview'),ah(async(req,res)=>{const b=req.body||{};const allowed=['asset_failure','equipment_shortage','location_closure','vendor_delay','unreturned_equipment','missing_critical_asset','demand_increase','venue_change'];if(!allowed.includes(b.type))throw badRequest('Unsupported logistics disruption type');let affectedAssets=[],alternativeStock=[],affectedRequests=[];if(b.assetId){const a=await M.Asset.findOne({assetId:b.assetId}).lean();if(!a)throw notFound('Asset not found');affectedAssets=[a];alternativeStock=await M.Asset.find({itemId:a.itemId,status:'available',assetId:{$ne:a.assetId}}).limit(20).lean();affectedRequests=await M.ResourceRequest.find({lines:{$elemMatch:{itemId:a.itemId}},status:{$in:['approved','reserved','dispatched']}}).lean();}if(b.locationId){if(!await M.Location.exists({locationId:b.locationId}))throw notFound('Location not found');affectedAssets=await M.Asset.find({locationId:b.locationId,status:{$in:['available','reserved','issued']}}).limit(500).lean();}const preview={type:b.type,affectedAssets:affectedAssets.map(a=>a.assetId),affectedRequests:affectedRequests.map(r=>r.requestId),alternatives:alternativeStock.map(a=>({assetId:a.assetId,assetTag:a.assetTag,locationId:a.locationId})),recoveryActions:alternativeStock.length?[{action:'reserve_replacement_assets',assetIds:alternativeStock.map(a=>a.assetId)}]:[{action:'review_transfer_or_purchase_order'}],noLiveChanges:true};const disruption=await M.LogisticsDisruption.create({disruptionId:makeId('LD'),type:b.type,params:b,preview,createdBy:actor(req)});res.status(201).json({disruption,preview});}));
logisticsApi.get('/logistics/disruptions',requirePerm('disruptions:read'),ah(async(_req,res)=>res.json({rows:await M.LogisticsDisruption.find({}).sort({createdAt:-1}).limit(200).lean()})));
logisticsApi.get('/logistics/disruptions/:id',requirePerm('disruptions:read'),ah(async(req,res)=>{const d=await M.LogisticsDisruption.findOne({disruptionId:req.params.id}).lean();if(!d)throw notFound('No disruption');res.json({disruption:d});}));
logisticsApi.post('/logistics/disruptions/:id/approve',requirePerm('disruptions:commit'),ah(async(req,res)=>{const d=await M.LogisticsDisruption.findOneAndUpdate({disruptionId:req.params.id,status:'previewed'},{$set:{status:'approved',approvedBy:actor(req),reason:req.body?.reason||''}},{new:true});if(!d)throw conflict('Disruption must be previewed before approval');res.json({disruption:d,approved:true});}));
logisticsApi.post('/logistics/disruptions/:id/execute',requirePerm('disruptions:commit'),ah(async(req,res)=>{const d=await M.LogisticsDisruption.findOne({disruptionId:req.params.id,status:'approved'});if(!d)throw conflict('Disruption must be approved first');if(['location_closure'].includes(d.type)){const loc=await M.Location.findOneAndUpdate({locationId:d.params.locationId,status:'active'},{$set:{status:'closed'}},{new:true});if(!loc)throw notFound('Active location not found');}else if(['asset_failure','missing_critical_asset','unreturned_equipment'].includes(d.type)&&d.params.assetId){const status=d.type==='asset_failure'?'maintenance':'missing';await M.Asset.updateOne({assetId:d.params.assetId},{$set:{status}});}else throw badRequest('This disruption type remains preview-only until its proposed recovery is approved through the relevant request/transfer/maintenance workflow');d.status='executed';d.executedBy=actor(req);d.result={executedAt:new Date(),entityIds:d.preview?.affectedAssets||[]};await d.save();emit('logistics.disruption.executed',{entity:{type:'LogisticsDisruption',id:d.disruptionId},impact:d.preview,at:new Date()});res.json({disruption:d,executed:true});}));
